 public static string EditorChecks(){Results.Clear();failures=0;var main=DungeonMapSettings.Current;Check(MakongRouteSetup.ValidateRoute(main).Contains("Makong True"),"BFS puertas por aristas: rojo → verde → maestra; sin atajo a Makong");
