 public static void Start(){EditorChecks();Finished=false;var lab=UnityEngine.Object.FindAnyObjectByType<CombatLaboratory>();lab.enabled=false;var d=lab.GetComponent<DungeonPrototype>();d.enabled=false;new GameObject("Map infrastructure checks").AddComponent<CombatTestRunner>().StartCoroutine(Run(lab,d));}
