 var regions=ScriptableObject.CreateInstance<DungeonRegionSettings>();regions.regions=new[]{new DungeonRegion{id="test",enemies=DungeonRegionSettings.Current.regions.First(r=>r.CanSpawn).enemies,cells=new List<Vector2Int>()}};for(int y=0;y<fixture.rows.Length;y++)for(int x=0;x<fixture.rows[y].Length;x++)if(fixture.IsFloor(new Vector2Int(x,y)))regions.regions[0].cells.Add(new Vector2Int(x,y));string potion=d.inventorySettings.items[0].id;regions.placedEnemies=new[]{new PlacedEnemyDefinition{id="route.test.guard",speciesId="BigTapaku",cell=new Vector2Int(5,4),randomLevel=false,fixedLevel=7,respawn=false,unique=true,countsTowardLimit=false,holdPosition=true,guaranteedDrops=new[]{new InventoryItemRecord{itemId=potion,quantity=1}}}};d.dungeonRegions=regions;Call(d,"SpawnPlacedEncounters");var objects=ScriptableObject.CreateInstance<DungeonEntitySettings>();objects.objects.Add(new DungeonMapEntity{id="route.test.key",kind=DungeonEntityKind.Chest,cell=new Vector2Int(3,4),chestKind=DungeonChestKind.KeyItem,contentId="key.red",guardPlacementId="route.test.guard"});objects.objects.Add(new DungeonMapEntity{id="route.test.door",kind=DungeonEntityKind.Door,cell=new Vector2Int(1,2),doorKind=DungeonDoorKind.Locked,requiredKeyId="key.red"});fixture.entities=objects;Call(d,"CreateMapEntities");Check((bool)Call(d,"MapDoorsBlock",(Vector3)Call(d,"World",new Vector2Int(1,2)),(Vector3)Call(d,"World",new Vector2Int(1,3))),"Puerta real bloquea sin llave");Call(d,"InteractMapEntity",objects.objects[0]);yield return new WaitForSecondsRealtime(.8f);Check(d.LaboratoryBattle,"Cofre inicia combate con guardián vivo");Check(!(bool)Call(d,"HasMapKey","key.red"),"Guardián impide recoger llave antes de vencer");
 var accuracy=ScriptableObject.CreateInstance<CombatAccuracySettings>();accuracy.enabledLuck=false;d.attackAccuracySettings=accuracy;int before=((int[])Get(d,"itemCounts"))[0];yield return (IEnumerator)Call(d,"ResolveCombatDamage",999,"ATTACK");Check(((int[])Get(d,"itemCounts"))[0]>=before+1,"Victoria entrega poción garantizada");Call(d,"InteractMapEntity",objects.objects[0]);yield return new WaitForSecondsRealtime(.8f);Check((bool)Call(d,"HasMapKey","key.red"),"Cofre entrega llave tras morir guardián");Call(d,"InteractMapEntity",objects.objects[1]);yield return new WaitForSecondsRealtime(2);Check(!(bool)Call(d,"MapDoorsBlock",(Vector3)Call(d,"World",new Vector2Int(1,2)),(Vector3)Call(d,"World",new Vector2Int(1,3))),"Puerta real abre con llave");var labels=(string[])Call(d,"CombatLabels");Check(d.inventorySettings.items.Count(i=>!i.keyItem)==3,"Llaves conservan tres consumibles de combate");int hp=(int)Get(d,"hp");Set(d,"hp",1);d.GainPlayerXP(d.XPRemaining);Check((int)Get(d,"hp")==d.PlayerStatValues[0],"Subida de nivel restaura todo HP");
 var save=d.CaptureDungeonSave();string json=JsonUtility.ToJson(save);d.RestoreDungeonSave(JsonUtility.FromJson<DungeonSaveData>(json));Check((bool)Call(d,"HasMapKey","key.red"),"Llave restaurada desde guardado");Check(d.CaptureEnemyProgression().Any(e=>e.placementId=="route.test.guard"&&e.defeated),"Guardián único permanece derrotado");before=((int[])Get(d,"itemCounts"))[0];Call(d,"InteractMapEntity",objects.objects[0]);yield return null;Check(((int[])Get(d,"itemCounts"))[0]==before,"Cofre y recompensa no se duplican al cargar");
 d.mapSettings=oldMap;d.dungeonRegions=oldRegions;Set(d,"map",oldMap.rows);lab.Choose();d.enabled=lab.enabled=true;UnityEngine.Object.Destroy(fixture);UnityEngine.Object.Destroy(objects);UnityEngine.Object.Destroy(regions);UnityEngine.Object.Destroy(accuracy);Results.Add("TOTAL "+(Results.Count-failures)+" PASS / "+failures+" FAIL");System.IO.Directory.CreateDirectory("Tests");System.IO.File.WriteAllLines("Tests/MapInfrastructureMcpResults.txt",Results);Finished=true;
